begin;set search_path to public,extensions;select plan(22);
insert into auth.users(id,email) values('a0000000-0000-4000-8000-000000000001','privacy-tenant@example.test'),('a0000000-0000-4000-8000-000000000002','privacy-landlord@example.test'),('a0000000-0000-4000-8000-000000000003','privacy-admin@example.test');
insert into private.administrator_grants(user_id,reason)values('a0000000-0000-4000-8000-000000000003','Synthetic account privacy administrator');
insert into public.properties(id,name,address,state,city,locality,property_type,rent_min,rent_max)values('a1000000-0000-4000-8000-000000000001','Synthetic privacy property','Synthetic privacy lane','Delhi','Privacy fixture city','Fixture area','Flat',1000,2000);
create temporary table privacy_profile as select public_profile_id from private.accounts where user_id='a0000000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
select create_review('{"property":"a1000000-0000-4000-8000-000000000001","start":"2025-01-01","current":true,"paid":1000,"propertyRating":4,"body":"Synthetic account deletion review","synthetic":true}');
reset role;create temporary table privacy_review as select id from public.reviews where body='Synthetic account deletion review';grant select on privacy_review to anon,authenticated,service_role;
insert into storage.objects(bucket_id,name,metadata)values('rental-documents','verification/a2000000-0000-4000-8000-000000000001.pdf','{"mimetype":"application/pdf"}'),('rental-documents','claim/a2000000-0000-4000-8000-000000000002.pdf','{"mimetype":"application/pdf"}');
set local role anon;select throws_ok($$select get_my_notifications()$$,'42501',null,'Anonymous notifications denied');
select throws_ok($$select get_media_purge_jobs(null)$$,'42501',null,'Purge paths private');
set local role authenticated;select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
select throws_ok($$select register_evidence_document('a0000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','pdf',(select id from privacy_review))$$,'42501',null,'User cannot bypass document processing');
set local role service_role;
select lives_ok($$select register_evidence_document('a0000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','pdf',(select id from privacy_review))$$,'Trusted PDF tenancy registration');
select lives_ok($$select register_evidence_document('a0000000-0000-4000-8000-000000000002','a2000000-0000-4000-8000-000000000002','pdf',null,'a1000000-0000-4000-8000-000000000001')$$,'Trusted PDF claim registration');
reset role;insert into private.review_photos(id,review_id,object_path)select 'a3000000-0000-4000-8000-000000000001',id,id::text||'/a3000000-0000-4000-8000-000000000001.jpg'from privacy_review;
create temporary table privacy_requests as select id from private.verification_requests where document_id='a2000000-0000-4000-8000-000000000001';create temporary table privacy_claim as select id from private.claims where document_id='a2000000-0000-4000-8000-000000000002';grant select on privacy_requests,privacy_claim to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000003',true);
select decide_verification((select id from privacy_requests),'approved','Synthetic private tenancy approval');select decide_claim((select id from privacy_claim),'approved','Synthetic private landlord approval');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000002',true);
select is(jsonb_array_length(get_my_notifications()),1,'Claim decision notifies owner');
select upsert_claimant_reply((select id from privacy_claim),(select id from privacy_review),'Synthetic representative reply for privacy tests');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
select is(jsonb_array_length(get_my_notifications()),2,'Tenant receives verification and reply notifications');
select ok(not(get_my_notifications()->0 ? 'user_id'),'Notification response excludes auth identity');
select is(get_authorized_document('a2000000-0000-4000-8000-000000000001'),'verification/a2000000-0000-4000-8000-000000000001.pdf','PDF authorized for owner');
select is(get_authorized_document('a2000000-0000-4000-8000-000000000002'),null::text,'Other owner PDF denied');
select lives_ok($$select mark_notification_read((get_my_notifications()->0->>'id')::uuid)$$,'Owner can mark read');
select throws_ok($$select mark_notification_read(gen_random_uuid())$$,'42501',null,'Foreign or missing notification denied');
reset role;delete from auth.users where id='a0000000-0000-4000-8000-000000000001';
select is((select count(*)::int from public.reviews where id=(select id from privacy_review)),0,'Deletion removes owned review');
select is((select count(*)::int from public.public_profiles where id=(select public_profile_id from privacy_profile)),0,'Deletion removes public alias');
select is((select count(*)::int from private.documents where owner_id='a0000000-0000-4000-8000-000000000001'),0,'Deletion removes evidence authorization');
select is((select count(*)::int from private.notifications where user_id='a0000000-0000-4000-8000-000000000001'),0,'Deletion removes private notifications');
select is((select count(*)::int from public.properties where id='a1000000-0000-4000-8000-000000000001'),1,'Public catalogue remains');
select is((select count(*)::int from private.claims where user_id='a0000000-0000-4000-8000-000000000002'),1,'Other account preserved');
select is((select count(*)::int from private.audit_events where action='account_deleted' and entity_id='a0000000-0000-4000-8000-000000000001'),1,'Account closure audited');
set local role service_role;
select is(jsonb_array_length(get_media_purge_jobs('a0000000-0000-4000-8000-000000000001')),2,'Registered document and photo queued for physical purge');
select is(get_photo_path('a3000000-0000-4000-8000-000000000001'),null::text,'Deleted photo immediately unavailable');
select lives_ok($$select finish_media_purge(array(select(j->>'id')::uuid from jsonb_array_elements(get_media_purge_jobs('a0000000-0000-4000-8000-000000000001'))j))$$,'Trusted storage worker acknowledges cleanup');
select * from finish();rollback;
